/** A node of a widget by name; throws when absent. */
export function widgetNode(widget: string, node: string): DemoWidgetNode {
  const found = demoWidgets[widget]?.nodes.find(n => n.name === node);
  if (!found) throw new Error(`${widget} has no node ${node}`);
  return found;
}
